(window.webpackJsonp=window.webpackJsonp||[]).push([[333],{667:function(t,r,a){"use strict";a.r(r);var e=a(33),s=Object(e.a)({},function(){var t=this,r=t.$createElement,a=t._self._c||r;return a("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[a("h1",{attrs:{id:"brott-i-lyftok-till-hjullastare"}},[a("a",{staticClass:"header-anchor",attrs:{href:"#brott-i-lyftok-till-hjullastare","aria-hidden":"true"}},[t._v("#")]),t._v(" Brott i lyftok till hjullastare")]),t._v(" "),a("p",[t._v("Ett brott i ett lyftok till en hjullastare inträffade efter onormalt kort drifttid. Oket var tillverkat av gjutstål, Ox 812. Efter okulär granskning av brottet konstaterades att detta hade en utpräglat spröd karaktär. Kännetecken på brottytan indikerade att brottet startat vid påsvetsade förstärkningsplåtar på okets ovansida. Okets utseende och läget för brottet framgår av nedanstående skiss.")]),t._v(" "),a("p",[t._v("Vid mikroskopisk undersökning av brottytan observerades små sprickor, 1–3 mm djupa, i anslutning till var och en av de tre stödplåtarna. Sprickorna låg nära de tvärgående svetsarnas smältgränser och kan ha uppstått i samband med svetsningen eller pga. utmattning under drift. Vid en kritisk storlek/påkänning har sprickorna initierat brott. Brottet hade startat vid de svetsar som låg tvärs över de stora påkänningarna i oket. Genom att avstå från dessa korta, och för stödplåtarnas funktion tämligen onödiga svetsar, skulle sannolikt risken för brott väsentligt ha reducerats.")]),t._v(" "),a("img",{attrs:{alt:"",height:"153",src:"https://eu1files.itslearning.com/data/1821/556/Hjullastare.jpg",width:"400"}})])},[],!1,null,null,null);r.default=s.exports}}]);